348	
349	    protected void setPetsInternal(Set<Pet> pets) {
350	        this.pets = pets;
351	    }
352	
353	    public List<Pet> getPets() {
354	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
355	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
356	        return Collections.unmodifiableList(sortedPets);
357	    }
358	
359	    public void setPets(List<Pet> pets) {
360	        this.pets = new HashSet<>(pets);
361	    }
362	
363	    public void addPet(Pet pet) {
364	        getPetsInternal().add(pet);
365	        pet.setOwner(this);
366	    }
367	
368	    /**
369	     * Return the Pet with the given name, or null if none found for this Owner.
370	     *
371	     * @param name to test
372	     * @return true if pet name is already in use
373	     */
374	    public Pet getPet(String name) {
375	        return getPet(name, false);
