377	
378	    /**
379	     * Return the Pet with the given name, or null if none found for this Owner.
380	     *
381	     * @param name to test
382	     * @return true if pet name is already in use
383	     */
384	    public Pet getPet(String name, boolean ignoreNew) {
385	        name = name.toLowerCase();
386	        for (Pet pet : getPetsInternal()) {
387	            if (!ignoreNew || !pet.isNew()) {
388	                String compName = pet.getName();
389	                compName = compName.toLowerCase();
390	                if (compName.equals(name)) {
391	                    return pet;
392	                }
393	            }
394	        }
395	        return null;
396	    }
397	
398	    public Pet getPet(Integer petId) {
399	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
400	    }
401	
402	    @Override
403	    public String toString() {
