16	package org.springframework.samples.petclinic.repository.jdbc;
17	import org.springframework.boot.sql.init.dependency.DependsOnDatabaseInitialization;
18	import org.springframework.context.annotation.Profile;
19	import org.springframework.dao.DataAccessException;
20	import org.springframework.dao.EmptyResultDataAccessException;
21	import org.springframework.data.domain.Page;
22	import org.springframework.data.domain.PageImpl;
23	import org.springframework.data.domain.Pageable;
24	import org.springframework.jdbc.core.BeanPropertyRowMapper;
25	import org.springframework.jdbc.core.namedparam.BeanPropertySqlParameterSource;
26	import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
27	import org.springframework.jdbc.core.simple.SimpleJdbcInsert;
28	import org.springframework.orm.ObjectRetrievalFailureException;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.PetType;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.repository.OwnerRepository;
34	import org.springframework.samples.petclinic.util.EntityUtils;
35	import org.springframework.stereotype.Repository;
36	
37	import javax.sql.DataSource;
38	import jakarta.transaction.Transactional;
39	import java.time.LocalDate;
40	import java.util.Collection;
41	import java.util.HashMap;
42	import java.util.List;
43	import java.util.Map;
44	
45	/**
46	 * A simple JDBC-based implementation of the {@link OwnerRepository} interface.
47	 *
48	 * @author Ken Krebs
49	 * @author Juergen Hoeller
50	 * @author Rob Harrop
51	 * @author Sam Brannen
52	 * @author Thomas Risberg
53	 * @author Mark Fisher
54	 * @author Antoine Rey
55	 * @author Vitaliy Fedoriv
56	 */
57	@DependsOnDatabaseInitialization
58	@Repository
59	@Profile("jdbc")
60	public class JdbcOwnerRepositoryImpl implements OwnerRepository {
61	
62	    private NamedParameterJdbcTemplate namedParameterJdbcTemplate;
63	
64	    private SimpleJdbcInsert insertOwner;
65	
66	    public JdbcOwnerRepositoryImpl(DataSource dataSource) {
67	
68	        this.insertOwner = new SimpleJdbcInsert(dataSource)
69	            .withTableName("owners")
70	            .usingGeneratedKeyColumns("id");
71	
72	        this.namedParameterJdbcTemplate = new NamedParameterJdbcTemplate(dataSource);
73	
74	    }
75	
76	
77	    /**
78	     * Loads {@link Owner Owners} from the data store by last name, returning all owners whose last name <i>starts</i> with
79	     * the given name; also loads the {@link Pet Pets} and {@link Visit Visits} for the corresponding owners, if not
80	     * already loaded.
81	     */
82	    @Override
83	    public Collection<Owner> findByLastName(String lastName) throws DataAccessException {
84	        Map<String, Object> params = new HashMap<>();
85	        params.put("lastName", lastName + "%");
86	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
87	            "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE last_name like :lastName",
88	            params,
89	            BeanPropertyRowMapper.newInstance(Owner.class)
90	        );
91	        loadOwnersPetsAndVisits(owners);
92	        return owners;
93	    }
94	
95	    @Override
96	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
97	        Map<String, Object> params = new HashMap<>();
98	        params.put("lastName", lastName + "%");
99	        params.put("size", pageable.getPageSize());
100	        params.put("offset", pageable.getOffset());
101	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
102	            "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE last_name like :lastName ORDER BY id LIMIT :size OFFSET :offset",
103	            params,
104	            BeanPropertyRowMapper.newInstance(Owner.class)
105	        );
106	        loadOwnersPetsAndVisits(owners);
107	        Long total = this.namedParameterJdbcTemplate.queryForObject(
108	            "SELECT COUNT(*) FROM owners WHERE last_name like :lastName",
109	            params,
110	            Long.class
111	        );
112	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
113	    }
114	
115	    /**
116	     * Loads the {@link Owner} with the supplied <code>id</code>; also loads the {@link Pet Pets} and {@link Visit Visits}
117	     * for the corresponding owner, if not already loaded.
118	     */
119	    @Override
120	    public Owner findById(int id) throws DataAccessException {
121	        Owner owner;
122	        try {
123	            Map<String, Object> params = new HashMap<>();
124	            params.put("id", id);
125	            owner = this.namedParameterJdbcTemplate.queryForObject(
126	                "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE id= :id",
127	                params,
128	                BeanPropertyRowMapper.newInstance(Owner.class)
129	            );
130	        } catch (EmptyResultDataAccessException ex) {
131	            throw new ObjectRetrievalFailureException(Owner.class, id);
132	        }
133	        loadPetsAndVisits(owner);
134	        return owner;
135	    }
136	
137	    @Override
138	    public Collection<Owner> findByTelephone(String telephone) throws DataAccessException {
139	        Map<String, Object> params = new HashMap<>();
140	        params.put("telephone", telephone);
141	        return this.namedParameterJdbcTemplate.query(
142	            "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE telephone = :telephone",
143	            params,
144	            BeanPropertyRowMapper.newInstance(Owner.class)
145	        );
146	    }
147	
148	    @Override
149	    public Collection<Owner> findByEmail(String email) throws DataAccessException {
150	        Map<String, Object> params = new HashMap<>();
151	        params.put("email", email);
152	        return this.namedParameterJdbcTemplate.query(
153	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE LOWER(email) = :email",
154	            params,
155	            BeanPropertyRowMapper.newInstance(Owner.class)
156	        );
157	    }
158	
159	    @Override
160	    public Collection<Owner> findByCustomerCode(String customerCode) throws DataAccessException {
161	        Map<String, Object> params = new HashMap<>();
162	        params.put("customerCode", customerCode);
163	        return this.namedParameterJdbcTemplate.query(
164	            "SELECT id, first_name, last_name, address, city, telephone, customer_code FROM owners WHERE customer_code = :customerCode",
165	            params,
166	            BeanPropertyRowMapper.newInstance(Owner.class)
167	        );
168	    }
169	
170	    public void loadPetsAndVisits(final Owner owner) {
171	        Map<String, Object> params = new HashMap<>();
172	        params.put("id", owner.getId());
173	        final List<JdbcPet> pets = this.namedParameterJdbcTemplate.query(
174	            "SELECT pets.id as pets_id, name, birth_date, type_id, owner_id, visits.id as visit_id, visit_date, description, visits.pet_id as visits_pet_id FROM pets LEFT OUTER JOIN visits ON pets.id = visits.pet_id WHERE owner_id=:id ORDER BY pets.id",
175	            params,
176	            new JdbcPetVisitExtractor()
177	        );
178	        Collection<PetType> petTypes = getPetTypes();
179	        for (JdbcPet pet : pets) {
180	            pet.setType(EntityUtils.getById(petTypes, PetType.class, pet.getTypeId()));
181	            owner.addPet(pet);
182	        }
183	    }
184	
185	    @Override
186	    public void save(Owner owner) throws DataAccessException {
187	        BeanPropertySqlParameterSource parameterSource = new BeanPropertySqlParameterSource(owner);
188	        if (owner.isNew()) {
189	            Number newKey = this.insertOwner.executeAndReturnKey(parameterSource);
190	            owner.setId(newKey.intValue());
191	        } else {
192	            this.namedParameterJdbcTemplate.update(
193	                "UPDATE owners SET first_name=:firstName, last_name=:lastName, address=:address, " +
194	                    "city=:city, telephone=:telephone WHERE id=:id",
195	                parameterSource);
196	        }
197	    }
198	
199	    public Collection<PetType> getPetTypes() throws DataAccessException {
200	        return this.namedParameterJdbcTemplate.query(
201	            "SELECT id, name FROM types ORDER BY name", new HashMap<String, Object>(),
202	            BeanPropertyRowMapper.newInstance(PetType.class));
203	    }
204	
205	    /**
206	     * Loads the {@link Pet} and {@link Visit} data for the supplied {@link List} of {@link Owner Owners}.
207	     *
208	     * @param owners the list of owners for whom the pet and visit data should be loaded
209	     * @see #loadPetsAndVisits(Owner)
210	     */
211	    private void loadOwnersPetsAndVisits(List<Owner> owners) {
212	        for (Owner owner : owners) {
213	            loadPetsAndVisits(owner);
214	        }
215	    }
216	
217		@Override
218		public Collection<Owner> findAll() throws DataAccessException {
219			List<Owner> owners = this.namedParameterJdbcTemplate.query(
220		            "SELECT id, first_name, last_name, address, city, telephone FROM owners",
221		            new HashMap<String, Object>(),
222		            BeanPropertyRowMapper.newInstance(Owner.class));
223			for (Owner owner : owners) {
224	            loadPetsAndVisits(owner);
225	        }
226		    return owners;
227		}
228	
229	    @Override
230	    public Page<Owner> findAll(Pageable pageable) throws DataAccessException {
231	        Map<String, Object> params = new HashMap<>();
232	        params.put("size", pageable.getPageSize());
233	        params.put("offset", pageable.getOffset());
234	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
235	            "SELECT id, first_name, last_name, address, city, telephone FROM owners ORDER BY id LIMIT :size OFFSET :offset",
236	            params,
237	            BeanPropertyRowMapper.newInstance(Owner.class));
238	        loadOwnersPetsAndVisits(owners);
239	        Long total = this.namedParameterJdbcTemplate.queryForObject(
240	            "SELECT COUNT(*) FROM owners",
241	            params,
242	            Long.class
243	        );
244	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
245	    }
246	
247		@Override
248		public long count() throws DataAccessException {
249			Long total = this.namedParameterJdbcTemplate.queryForObject(
250				"SELECT COUNT(*) FROM owners",
251				new HashMap<String, Object>(),
252				Long.class);
253			return total == null ? 0 : total;
254		}
255	
256		@Override
257		public long countByCity(String city) throws DataAccessException {
258			Map<String, Object> params = new HashMap<>();
259			params.put("city", city);
260			Long total = this.namedParameterJdbcTemplate.queryForObject(
261				"SELECT COUNT(*) FROM owners WHERE city = :city",
262				params,
263				Long.class);
264			return total == null ? 0 : total;
265		}
266	
267		@Override
268		public long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
269			Map<String, Object> params = new HashMap<>();
270			params.put("registrationDate", registrationDate);
271			Long total = this.namedParameterJdbcTemplate.queryForObject(
272				"SELECT COUNT(*) FROM owners WHERE registration_date = :registrationDate",
273				params,
274				Long.class);
275			return total == null ? 0 : total;
276		}
277	
278		@Override
279		@Transactional
280		public void delete(Owner owner) throws DataAccessException {
281			Map<String, Object> ownerParams = new HashMap<>();
282			ownerParams.put("id", owner.getId());
283	        List<Pet> pets = owner.getPets();
284	        // cascade delete pets
285	        for (Pet pet : pets){
286	        	Map<String, Object> petParams = new HashMap<>();
287	        	petParams.put("id", pet.getId());
288	        	// cascade delete visits
289	        	List<Visit> visits = pet.getVisits();
290	            for (Visit visit : visits){
291	            	Map<String, Object> visitParams = new HashMap<>();
292	            	visitParams.put("id", visit.getId());
293	            	this.namedParameterJdbcTemplate.update("DELETE FROM visits WHERE id=:id", visitParams);
294	            }
295	            this.namedParameterJdbcTemplate.update("DELETE FROM pets WHERE id=:id", petParams);
296	        }
297	        this.namedParameterJdbcTemplate.update("DELETE FROM owners WHERE id=:id", ownerParams);
298		}
299	
300	
301	}
